#!/usr/bin/env node
import { McpServer } from "@modelcontextprotocol/server";
import { serveStdio } from "@modelcontextprotocol/server/stdio";

import { registerTools } from "./tools.js";

// stdout is the protocol: log to stderr, never console.log.
serveStdio(
  () => {
    const server = new McpServer({ name: "{{name}}", version: "0.1.0" });
    registerTools(server);
    return server;
  },
  { onerror: (error) => process.stderr.write(`[{{name}}] ${error.message}\n`) },
);

import type { McpServer } from "@modelcontextprotocol/server";
import { z } from "zod";

/** One function per tool: a clear name, a description the model reads, and a Zod schema. */
export function registerTools(server: McpServer) {
  server.registerTool(
    "greet",
    {
      title: "Greet",
      description: "Greets a person by name.",
      inputSchema: z.object({ name: z.string().describe("Who to greet") }),
      annotations: { readOnlyHint: true, openWorldHint: false },
    },
    async ({ name }) => ({ content: [{ type: "text", text: `Hello, ${name}!` }] }),
  );
}
